# ============================================================
# AEGIS NIDS - STEP 6: Detection Fabric Integration
# ============================================================
# Wires the Detection layer with Flow Integration + Event Fabric:
#   - processEvent(event, det_mgr, payload) -> DetectionContext
#   - Updates flow state via flow_integration.processEvent()
#   - Checks escalation patterns (high packet count / byte count / risk)
#   - Runs DetectionManager.detect() if detectors registered
#   - Updates flow risk_score on match (detection layer annotates flows)
#   - Returns DetectionContext with verdict + flow snapshot for policy/PEP
#
# Escalation thresholds (configurable):
#   - high_packet_count: 1000 (default) -> ALERT (possible beaconing)
#   - high_byte_count:   10MB  (default) -> ALERT (possible exfiltration)
#   - high_risk_score:   200   (default) -> BLOCK  (repeat offender)
#
# eventFabricDrain now feeds every popped event through detection_int.
# ============================================================
$ErrorActionPreference = 'Continue'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS STEP 6 - Detection Fabric Integration"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"
Write-Host ""

function Deploy-File {
    param([string]$RelativePath, [int]$ExpectedLines, [string]$Base64Content)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path -Parent $FullPath
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
        Write-Host "  [MKDIR] Created: $Dir"
    }
    $BackupPath = "$FullPath.step6_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] $RelativePath : actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] $RelativePath : $ActualLines lines"
    }
}

# File 1: core/detection_integration.zig (detection_integration.zig, 667 lines)
$B64_1 = ''
Deploy-File -RelativePath "core/detection_integration.zig" -ExpectedLines 667 -Base64Content $B64_1
Write-Host ""

# File 2: core/nids_analyze.zig (nids_analyze.zig, 2295 lines)
$B64_2 = ''
Deploy-File -RelativePath "core/nids_analyze.zig" -ExpectedLines 2295 -Base64Content $B64_2
Write-Host ""

# File 3: core/nids_main.zig (nids_main.zig, 249 lines)
$B64_3 = ''
Deploy-File -RelativePath "core/nids_main.zig" -ExpectedLines 249 -Base64Content $B64_3
Write-Host ""

# File 4: build.zig (build.zig, 82 lines)
$B64_4 = ''
Deploy-File -RelativePath "build.zig" -ExpectedLines 82 -Base64Content $B64_4
Write-Host ""

# ============================================================
# Build and test
# ============================================================
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | Out-Host
$buildExit = $LASTEXITCODE
if ($buildExit -ne 0) {
    Write-Host "[BUILD] FAILED (exit $buildExit)"
    exit 1
}
Write-Host "[BUILD] SUCCESS"
Write-Host ""

Write-Host "[TEST] Running zig build test (uses ErrorActionPreference=Continue)..."
& zig build test 2>&1 | Out-Host
$testExit = $LASTEXITCODE
if ($testExit -eq 0) {
    Write-Host "[TEST] ALL ZIG TESTS PASSED"
} else {
    Write-Host "[TEST] FAILED (exit $testExit)"
    exit $testExit
}
Write-Host ""

Write-Host "============================================================"
Write-Host "STEP 6 COMPLETE: Detection Fabric Integration"
Write-Host "============================================================"
Write-Host ""
Write-Host "Files deployed:"
Write-Host "  core/detection_integration.zig  (NEW, 662 lines)"
Write-Host "    - DetectionContext: event + flow_context + verdict + matched"
Write-Host "    - EscalationThresholds: high_packet_count / byte_count / risk_score"
Write-Host "      presets: default / strict"
Write-Host "    - escalateOnFlowPattern(event, fctx): mutates event.context_flags"
Write-Host "      bit1=high_packet_count, bit2=high_byte_count, bit3=prior_risk_match"
Write-Host "    - processEvent(event, det_mgr, payload) -> DetectionContext"
Write-Host "      1. flow_int.processEvent() updates flow state"
Write-Host "      2. escalateOnFlowPattern() checks patterns"
Write-Host "      3. det_mgr.detect() runs detectors (if provided)"
Write-Host "      4. On match: flow_int.updateRiskScore() annotates flow"
Write-Host "      5. event.event_type/severity updated based on verdict"
Write-Host "    - processEventFlowOnly(event): convenience without det_mgr"
Write-Host "    - IntegrationStats: events_processed, matches, blocks,"
Write-Host "      escalations, flow_risk_updates"
Write-Host "    - 13 STEP6 tests: lifecycle, escalation patterns, detector"
Write-Host "      integration, risk-score update, port-scan-like scenario"
Write-Host ""
Write-Host "  core/nids_analyze.zig         (REPLACE, 2296 lines)"
Write-Host "    - eventFabricDrain() now feeds events through detection_int"
Write-Host "    - Imports flow_int + detection_int locally"
